def matrix_max_path_sum(matrix):
    if not matrix or not matrix[0]:
        return 0
    dp = [0] * len(matrix[0])
    for i, row in enumerate(matrix):
        for j, value in enumerate(row):
            if i == 0 and j == 0:
                dp[j] = value
            elif i == 0:
                dp[j] = dp[j - 1] + value
            elif j == 0:
                dp[j] = dp[j] + value
            else:
                dp[j] = max(dp[j], dp[j - 1]) + value
    return dp[-1]
